css:
.pv{--bg:#FFFFFF;--body:#FAFAFA;--muted:#F5F5F5;--hov:#F5F5F5;--fg:#171717;--fg2:#525252;--fg3:#737373;--line:#E5E5E5;--line2:#D4D4D4;--input:#737373;--focus:#262626;--badge:#B42318;
 --solid:#262626;--on:#FFFFFF;--err:#B42318;--info:#1F4FB8;--info-bg:#E7EFFD;--ok:#1B7542;--ok-bg:#E8F5EC;--warn:#8A5300;--warn-bg:#FFF3DC;
 --mark:#FFF1B8;--shadow:0 12px 32px rgba(10,10,10,.14),0 2px 6px rgba(10,10,10,.06);--scrim:rgba(10,10,10,.4);
 font:14px/20px Inter,system-ui,sans-serif;color:var(--fg);background:var(--bg)}
.pv[data-theme=dark]{--bg:#0A0A0A;--body:#111111;--muted:#1C1C1C;--hov:#1C1C1C;--fg:#FAFAFA;--fg2:#C4C4C4;--fg3:#A3A3A3;--line:#262626;--line2:#404040;--input:#A3A3A3;--focus:#FAFAFA;--badge:#B42318;
 --solid:#FAFAFA;--on:#0A0A0A;--err:#FFA19C;--info:#93B9FF;--info-bg:#11203F;--ok:#93CFA6;--ok-bg:#0F2A19;--warn:#E3B87A;--warn-bg:#332006;--mark:#5A4A0A;
 --shadow:0 12px 32px rgba(0,0,0,.6);--scrim:rgba(0,0,0,.6)}
.i{flex:none;display:block}
.mono{font-family:"JetBrains Mono",ui-monospace,Menlo,monospace;font-size:.92em}
.b{font-weight:600}.mut{color:var(--fg3)}
kbd{font:500 11px/16px Inter;color:var(--fg3);border:1px solid var(--line2);border-radius:4px;padding:0 4px;background:var(--bg)}
mark{background:var(--mark);color:inherit;border-radius:2px;padding:0 1px}
/* khung */
.app{display:flex;min-height:720px;background:var(--bg);position:relative}
.sb{width:240px;flex:none;border-right:1px solid var(--line);padding:12px;display:flex;flex-direction:column;gap:2px;background:var(--bg)}
.sb .lg{display:flex;align-items:center;gap:8px;padding:4px 6px 14px;font:400 18px "Cal Sans",Inter}
.sb .lo{width:28px;height:28px;border-radius:8px;background:#0036B5;color:#fff;display:grid;place-items:center;font:600 12px Inter}
.sb .gh{font:600 11px/16px Inter;letter-spacing:.05em;text-transform:uppercase;color:var(--fg3);padding:14px 8px 4px}
.sb .it{display:flex;align-items:center;gap:10px;height:36px;padding:0 10px;border-radius:8px;color:var(--fg2);font-weight:500}
.sb .it.on{background:var(--muted);color:var(--fg);font-weight:600}
.sb .it .c{margin-left:auto;font:600 11px/18px Inter;color:var(--info);background:var(--info-bg);border-radius:999px;padding:0 7px}
.sb .sc{margin-top:auto;border:1px solid var(--line);border-radius:12px;padding:8px;display:flex;gap:8px;align-items:center;font-size:13px}
.sb .sc .mt{width:32px;height:32px;border-radius:8px;background:var(--info-bg);color:var(--info);display:grid;place-items:center;flex:none}
.sb .sc b{display:block;font-weight:600}.sb .sc span{display:flex;gap:4px;align-items:center;color:var(--fg3);font-size:12px}
.sb .sc>svg:last-child{margin-left:auto;color:var(--fg3)}
.mn{flex:1;min-width:0;display:flex;flex-direction:column;position:relative}
/* thanh trên */
.hd{height:56px;display:flex;align-items:center;gap:8px;padding:0 24px;border-bottom:1px solid var(--line);background:var(--bg)}
.hd2{height:44px;display:flex;align-items:flex-end;gap:20px;padding:0 24px;border-bottom:1px solid var(--line);background:var(--bg)}
.hd2 .tb{padding-bottom:10px;font-weight:600;color:var(--fg3)}.hd2 .tb.on{color:var(--fg);box-shadow:inset 0 -2px 0 var(--solid)}
.hl{min-width:0;flex:0 1 auto;overflow:hidden}
.sp{flex:1}
.ib{width:36px;height:36px;border-radius:8px;border:0;background:transparent;color:var(--fg2);display:grid;place-items:center;position:relative;cursor:pointer;flex:none}
.ib:hover{background:var(--hov);color:var(--fg)}
.bell .nd{position:absolute;top:8px;right:9px;width:8px;height:8px;border-radius:50%;background:var(--err);box-shadow:0 0 0 2px var(--bg)}
.bell .nc{position:absolute;top:-1px;right:-3px;min-width:18px;height:18px;padding:0 5px;border-radius:999px;font:600 11px/18px Inter;
 background:var(--info);color:#fff;box-shadow:0 0 0 2px var(--bg)}
.pv[data-theme=dark] .bell .nc{color:#0A0A0A}
.pv[data-D5=c] .bell .nc,.pv[data-theme=dark] .pv[data-D5=c] .bell .nc{background:var(--badge);color:#fff}
.pv[data-state=zero] .bell .nd,.pv[data-state=zero] .bell .nc{display:none}
.pv[data-state=notif] .bell,.pv[data-state=account] .acc{background:var(--muted);color:var(--fg)}
.sbx{width:280px;height:36px;border:1px solid var(--input);border-radius:8px;display:flex;align-items:center;gap:8px;padding:0 8px 0 10px;color:var(--fg3);background:var(--bg);flex:none;margin-right:4px}
.sbx .ph{flex:1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sbx .q{display:none;flex:1;color:var(--fg)}
.pv[data-state=search] .sbx .ph,.pv[data-state=noresult] .sbx .ph{display:none}
.pv[data-state=search] .sbx .q1,.pv[data-state=noresult] .sbx .q2{display:block}
.pv[data-state=search] .sbx,.pv[data-state=noresult] .sbx{border-color:var(--focus);box-shadow:0 0 0 1px var(--focus)}
.pv[data-D2=c] .sbx{position:absolute;left:50%;transform:translateX(-50%);width:420px;top:10px}
.acc{display:flex;align-items:center;gap:8px;height:40px;padding:0 6px 0 4px;border:0;border-radius:10px;background:transparent;color:var(--fg);cursor:pointer;margin-left:4px;max-width:260px;font:inherit}
.acc:hover{background:var(--hov)}
.av{width:32px;height:32px;border-radius:50%;background:var(--muted);border:1px solid var(--line);display:grid;place-items:center;font:600 12px Inter;color:var(--fg2);flex:none}
.av.lg{width:40px;height:40px;font-size:14px}.av.sm{width:30px;height:30px;font-size:11px}
.acc .nm{display:flex;flex-direction:column;min-width:0;text-align:left}
.acc .n1{font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:160px}
.acc .n2{font-size:12px;line-height:16px;color:var(--fg3);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:180px}
.acc .cv{color:var(--fg3)}
/* breadcrumb */
.bc{display:flex;align-items:center;gap:2px;min-width:0;font:500 14px/20px Inter;color:var(--fg3);white-space:nowrap}
.bc .cw{display:contents}
.bc .sep{color:var(--line2);display:grid;place-items:center;width:16px;flex:none}
.bc .ci{color:var(--fg3);text-decoration:none;display:inline-flex;align-items:center;gap:2px;border:0;background:none;font:inherit;padding:0;cursor:pointer;min-width:0}
.bc .ci:hover{color:var(--fg)}
.bc .cur{color:var(--fg);font-weight:600;cursor:default}
.bc .hm{color:var(--fg3)}
.bc .el{width:24px;justify-content:center}
.bc .sib{color:var(--fg3);margin-left:1px}
.pv[data-D6=b] .bc .ci{height:28px;padding:0 8px;border-radius:6px}
.pv[data-D6=b] .bc .ci:hover{background:var(--hov)}
.pv[data-D6=b] .bc .cur{background:var(--muted)}
.pv[data-D6=b] .bc .sep{width:12px}
.pv[data-D6=c] .bc .ci{height:36px;box-shadow:inset 0 -2px 0 transparent}
.pv[data-D6=c] .bc .cur{box-shadow:inset 0 -2px 0 var(--solid)}
.pv[data-D6=c] .hd .bc{align-self:stretch}
.pv[data-D7=b] .bc .ci:not(.hm){max-width:150px}
.pv[data-D7=b] .bc .ci>span:first-child{overflow:hidden;text-overflow:ellipsis}
.pv[data-D7=b][data-state=long] .bc .ci:not(.hm):not(.cur){display:inline-block;overflow:hidden;text-overflow:ellipsis;max-width:120px}
.pcb{margin-bottom:6px}
/* nội dung */
.ct{padding:24px;background:var(--bg);flex:1}
.ph1{display:flex;justify-content:space-between;align-items:flex-end;margin-bottom:16px}
.ph1 h1{font:400 24px/32px "Cal Sans",Inter;margin:0}
.sub{margin:2px 0 0;color:var(--fg3)}
.tbl{width:100%;border-collapse:collapse;font-size:13px}
.tbl th{text-align:left;font-weight:500;color:var(--fg3);background:var(--body);height:40px;padding:0 12px;border-bottom:1px solid var(--line)}
.tbl td{height:52px;padding:0 12px;border-bottom:1px solid var(--line);white-space:nowrap}
.chip{display:inline-flex;align-items:center;gap:5px;height:22px;padding:0 8px;border-radius:999px;font:500 12px/18px Inter}
.chip:before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor}
.chip.info{color:var(--info);background:var(--info-bg)}.chip.ok{color:var(--ok);background:var(--ok-bg)}.chip.warn{color:var(--warn);background:var(--warn-bg)}
.cards{display:grid;grid-template-columns:1fr 1fr;gap:16px}
.card{border:1px solid var(--line);border-radius:12px;padding:16px;display:grid;gap:10px}
.card h3{margin:0;font:600 16px/24px Inter}
.fl{display:grid;gap:4px;font-size:13px}.fl>span{color:var(--fg2);font-weight:500}
.fi{height:36px;border:1px solid var(--line2);border-radius:8px;padding:0 10px;display:flex;align-items:center}
.fi.ph{color:var(--fg3)}
.form{max-width:560px;display:grid;gap:14px}
.fa{display:flex;gap:8px;justify-content:flex-end}
.btn{height:36px;padding:0 14px;border-radius:8px;background:var(--muted);font-weight:600;display:inline-flex;align-items:center}
.btn.pri{background:var(--solid);color:var(--on)}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}
.kpi{border:1px solid var(--line);border-radius:12px;padding:12px 14px;display:grid}.kpi span{color:var(--fg3);font-size:13px}.kpi b{font:600 24px/32px Inter}
/* bảng tìm tính năng */
.pal{position:absolute;top:52px;right:196px;width:440px;background:var(--bg);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);z-index:20;overflow:hidden}
.pv[data-D2=c] .pal{right:auto;left:50%;transform:translateX(-50%);width:480px}
.pv[data-D2=b] .pal{top:96px;left:50%;right:auto;transform:translateX(-50%);width:600px;z-index:31}
.scr{position:absolute;inset:0;background:var(--scrim);z-index:30}
.pin{display:flex;align-items:center;gap:10px;height:52px;padding:0 16px;border-bottom:1px solid var(--line);font-size:16px}
.pin span{flex:1}
.pg{font:600 11px/16px Inter;letter-spacing:.05em;text-transform:uppercase;color:var(--fg3);padding:12px 16px 4px}
.pr{display:flex;align-items:center;gap:10px;min-height:44px;padding:4px 16px;cursor:pointer}
.pr.on{background:var(--muted)}
.pr .pi{width:28px;height:28px;border-radius:8px;border:1px solid var(--line);display:grid;place-items:center;color:var(--fg2);flex:none}
.pr .pt{flex:1;display:flex;flex-direction:column;min-width:0;font-weight:500}.pt1{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ps{font-size:12px;line-height:16px;color:var(--fg3);font-weight:400}
.pr>svg{color:var(--fg3)}
.pe{padding:28px 16px;display:grid;gap:4px;text-align:center}.pe span{color:var(--fg3);font-size:13px}
.pf{display:flex;gap:14px;padding:8px 16px;border-top:1px solid var(--line);font-size:12px;color:var(--fg3);background:var(--body)}
.pf span:last-child{margin-left:auto}
/* menu tài khoản */
.am{position:absolute;top:52px;right:24px;width:280px;background:var(--bg);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);z-index:20;padding:6px}
.am .mh{display:flex;gap:10px;align-items:center;padding:8px 10px 12px;border-bottom:1px solid var(--line);margin-bottom:6px}
.am .mh b{display:block;font-weight:600}.am .mh>div>span{display:block;font-size:12px;line-height:16px;color:var(--fg3)}
.mi{display:flex;align-items:center;gap:10px;height:36px;padding:0 10px;border-radius:8px;color:var(--fg2);font-weight:500}
.mi span{flex:1;color:var(--fg)}.mi:hover{background:var(--hov)}
.mi .mv{flex:none;color:var(--fg3);font-weight:400}
.mi.dng,.mi.dng span{color:var(--err)}
.msep{height:1px;background:var(--line);margin:6px 0}
/* panel thông báo (Notification Center, chỉ minh hoạ vị trí neo) */
.np{position:absolute;top:52px;right:72px;width:380px;background:var(--bg);border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow);z-index:20;overflow:hidden}
.np .nh{display:flex;justify-content:space-between;align-items:center;padding:12px 16px}.np .lk{font-size:13px;color:var(--fg2);font-weight:600}
.ntab{display:flex;gap:16px;padding:0 16px;border-bottom:1px solid var(--line);font-weight:600;color:var(--fg3)}
.ntab span{padding-bottom:8px}.ntab .on{color:var(--fg);box-shadow:inset 0 -2px 0 var(--solid)}
.ntab b{font:600 11px/16px Inter;background:var(--muted);border-radius:999px;padding:0 6px;color:var(--fg2)}
.nr{display:flex;gap:10px;padding:12px 16px;border-bottom:1px solid var(--line);font-size:13px}
.nr.un{background:var(--info-bg)}.nr .ud{width:8px;height:8px;border-radius:50%;margin-top:6px;flex:none}
.nr.un .ud{background:var(--info)}.nr b{display:block}
/* mobile web */
.mweb{background:var(--bg);min-height:720px;position:relative}
.mhd{height:56px;display:flex;align-items:center;gap:4px;padding:0 8px 0 4px;border-bottom:1px solid var(--line);background:var(--bg)}
.mhd .mt1{display:flex;align-items:center;gap:2px;min-width:0;font-size:15px;white-space:nowrap;overflow:hidden}
.mhd .mt1 b{overflow:hidden;text-overflow:ellipsis;min-width:0}
.mhd .av{margin-left:4px}
.mhd .sep{color:var(--line2)}
.mback{display:flex;align-items:center;gap:4px;height:40px;padding:0 12px;color:var(--fg2);font-weight:500;border-bottom:1px solid var(--line)}
.mbody{padding:16px}
.mh1{font:400 22px/28px "Cal Sans",Inter;margin:0}
.mr{display:grid;grid-template-columns:1fr auto;gap:2px 8px;padding:12px 0;border-bottom:1px solid var(--line);font-size:13px}
.mr .mut{grid-column:1/-1}
.mpal{position:absolute;inset:0;background:var(--bg);z-index:30}
.pv:not([data-D2="a"]):not([data-D2="c"]) [data-any="D2:a D2:c"],.pv:not([data-D3="b"]):not([data-D3="c"]) [data-any="D3:b D3:c"],.pv:not([data-D4="a"]):not([data-D4="c"]) [data-any="D4:a D4:c"],.pv:not([data-D5="b"]):not([data-D5="c"]) [data-any="D5:b D5:c"],.pv:not([data-D7="b"]):not([data-D7="c"]) [data-any="D7:b D7:c"],.pv:not([data-state="default"]):not([data-state="search"]):not([data-state="noresult"]):not([data-state="notif"]):not([data-state="account"]):not([data-state="zero"]) [data-any="state:default state:search state:noresult state:notif state:account state:zero"],.pv:not([data-state="search"]):not([data-state="noresult"]) [data-any="state:search state:noresult"]{display:none!important}.pv[data-theme=dark] .pv{--bg:#0A0A0A;--body:#111111;--muted:#1C1C1C;--hov:#1C1C1C;--fg:#FAFAFA;--fg2:#C4C4C4;--fg3:#A3A3A3;--line:#262626;--line2:#404040;--input:#A3A3A3;--focus:#FAFAFA;--badge:#B42318;
 --solid:#FAFAFA;--on:#0A0A0A;--err:#FFA19C;--info:#93B9FF;--info-bg:#11203F;--ok:#93CFA6;--ok-bg:#0F2A19;--warn:#E3B87A;--warn-bg:#332006;--mark:#5A4A0A;
 --shadow:0 12px 32px rgba(0,0,0,.6);--scrim:rgba(0,0,0,.6)}
.bc .cur{display:inline-block;max-width:240px;overflow:hidden;text-overflow:ellipsis;vertical-align:middle}.pv[data-D6=b] .bc .cur{line-height:28px}.pv[data-D6=c] .bc .cur{line-height:36px}
.bc .ci.hv{color:var(--fg)}.bc .ci.fc,.sbx.fc,.ib.fc,.acc.fc{outline:2px solid var(--focus);outline-offset:2px;border-radius:6px}
.pv[data-D6=b] .bc .ci.hv{background:var(--hov)}.pv[data-D6=c] .bc .ci.hv{box-shadow:inset 0 -2px 0 var(--line2)}
.sbx.hv{border-color:var(--fg2)}.sbx .q.on{display:block}.sbx.typ{border-color:var(--focus);box-shadow:0 0 0 1px var(--focus)}
.ib.hv,.acc.hv{background:var(--hov);color:var(--fg)}.ib.op,.acc.op{background:var(--muted);color:var(--fg)}
.ib.fc,.acc.fc{border-radius:8px}
.tw{position:relative;display:inline-flex;flex-direction:column;align-items:center;gap:6px}
.tip{background:var(--solid);color:var(--on);font:500 12px/18px Inter;padding:4px 8px;border-radius:6px;white-space:nowrap}
.acc.only{padding:2px;height:36px;width:36px;justify-content:center;border-radius:50%;margin:0}
.pv[data-D4=b] .hd .acc{padding:2px;width:36px;height:36px;justify-content:center;border-radius:50%}
.elw{position:relative;display:inline-flex}.bc .ci.el.op{background:var(--muted);border-radius:6px;color:var(--fg)}
.elm{position:absolute;top:28px;left:-8px;min-width:220px;background:var(--bg);border:1px solid var(--line);border-radius:10px;box-shadow:var(--shadow);padding:4px;z-index:5}
.elm a{display:flex;align-items:center;gap:8px;height:36px;padding:0 10px;border-radius:6px;color:var(--fg);font-weight:500;white-space:nowrap}
.elm a:hover{background:var(--hov)}
.static .pal,.static .am{position:static;transform:none}
.static{position:relative}
.ex{display:flex;flex-direction:column;gap:6px;width:max-content}
.lab{font:500 11px Inter;color:var(--fg3)}
.mhd .acc.m{padding:0;height:36px;width:36px;justify-content:center;margin:0}
.mscr{position:absolute;inset:0;background:var(--scrim);z-index:30}
.msh{position:absolute;left:0;right:0;bottom:0;background:var(--bg);border-radius:16px 16px 0 0;padding:8px 8px 24px;z-index:31}
.msh .grab{display:block;width:36px;height:4px;border-radius:2px;background:var(--line2);margin:0 auto 8px}
.msh .mh{display:flex;gap:12px;align-items:center;padding:8px 12px 14px;border-bottom:1px solid var(--line);margin-bottom:6px}
.msh .mh b{display:block}.msh .mh>div>span{display:block;font-size:13px;line-height:18px;color:var(--fg3)}
.msi{display:flex;align-items:center;gap:12px;min-height:48px;padding:0 12px;border-radius:10px;color:var(--fg2);font:500 15px/22px Inter}
.msi span{flex:1;color:var(--fg)}.msi .mv{flex:none;color:var(--fg3);font-weight:400}.msi.dng,.msi.dng span{color:var(--err)}
.mnp{position:absolute;inset:0;background:var(--bg);z-index:30}.mnp .lk{font-size:13px;font-weight:600;color:var(--fg2);padding-right:8px}
.mweb .pal-m{position:static}

.pv{--mark:#FEE4B6}
.hd2{height:40px}.elm{min-width:240px}
.sbx{width:300px;height:32px}kbd{font-size:12px}
.pal{width:400px;right:64px}.pg{font-size:12px}.pr{min-height:40px}.pf{gap:12px}
.pe{padding:24px 16px}.pe span{font-size:12px}
.bell .nc{min-width:20px;height:20px;padding:0 4px;font:600 12px/20px Inter}
.am{width:300px}.mhd .av.sm{width:28px;height:28px}.mpal .pin{font-size:17px}
